  "Wie findest du das Sofa?": "ሶፋውን እንዴት አየኸው/አየሽው?",
  "Wie findest du …?": "… እንዴት ይመስልሃል/ይመስልሻል?",
  "Wie gefallen dir …?": "… (ብዙ ነገሮች) እንዴት ይመስሉሃል/ይመስሉሻል?",
  "Wie gefällt Ihnen …?": "… እንዴት ይመስልዎታል?",
  "Wie gefällt dir …?": "… እንዴት ይመስልሃል/ይመስልሻል? / ወደድከው/ወደድሽው?",
  "Wie geht es Ihnen?": "እንዴት ነዎት?",
  "Wie geht es dir?": "እንዴት ነህ/ነሽ?",
