  "Wie heißen Sie?": "ስምዎ ማን ነው?",
  "Wie heißt das auf Deutsch?": "ይህ በጀርመንኛ ምን ይባላል?",
  "Wie heißt du?": "ስምህ/ስምሽ ማን ነው?",
  "Wie ist Ihr Name, bitte?": "ስምዎ ማን ነው፣ እባክዎ?",
  "Wie ist das Wetter?": "የአየር ሁኔታው እንዴት ነው?",
  "Wie ist dein Name?": "ስምህ/ስምሽ ማን ነው?",
  "Wie ist deine E-Mail-Adresse?": "የኢሜይል አድራሻህ/አድራሻሽ ምንድን ነው?",
  "Wie ist deine Telefonnummer?": "ስልክ ቁጥርህ/ቁጥርሽ ስንት ነው?",
  "Wie ist deine Wohnung?": "ቤትህ/ቤትሽ እንዴት ነው?",
