  "<em class=\"de\">sch</em> is simply English \"sh\": <em class=\"de\">Schule</em>. At the start of a word, <em class=\"de\">sp</em> and <em class=\"de\">st</em> sound like \"shp\" and \"sht\": <em class=\"de\">sprechen</em>, <em class=\"de\">Stadt</em>.": "<em class=\"de\">sch</em> ልክ እንደ «ሸ» ነው፦ <em class=\"de\">Schule</em> = «ሹለ»። በቃል መጀመሪያ ላይ <em class=\"de\">sp</em> እና <em class=\"de\">st</em> «ሽፕ» እና «ሽት» ይባላሉ፦ <em class=\"de\">sprechen</em>፣ <em class=\"de\">Stadt</em>።",
