  "Which ch is in \"nicht\"?": "በ«nicht» ውስጥ የትኛው ch ነው?",
  "After l: soft.": "ከl በኋላ፦ ለስላሳ።",
  "Which ch is in \"Milch\"?": "በ«Milch» ውስጥ የትኛው ch ነው?",
