  "How do you say the chs in \"sechs\"?": "በ«sechs» ውስጥ ያለውን chs እንዴት ይሉታል?",
  "You need numbers from day one: phone numbers, prices, times, your age, your house number.": "ቁጥሮች ከመጀመሪያው ቀን ጀምሮ ያስፈልግዎታል፦ የስልክ ቁጥር፣ ዋጋ፣ ሰዓት፣ ዕድሜዎ፣ የቤት ቁጥርዎ።",
  "The numbers 1 to 12 each have their own name. From 13 on, German builds numbers out of these, so learn these twelve well.": "ከ1 እስከ 12 ያሉት ቁጥሮች እያንዳንዳቸው የራሳቸው ስም አላቸው። ከ13 ጀምሮ ጀርመንኛ ቁጥሮችን ከእነዚህ ይገነባል፤ ስለዚህ እነዚህን አሥራ ሁለቱን በደንብ ይማሩ።",
  "The numbers": "ቁጥሮቹ",
  "One to twelve": "ከአንድ እስከ አሥራ ሁለት",
  "Press a speaker to hear each number. The last column gives a rough English guide.": "እያንዳንዱን ቁጥር ለመስማት የድምፅ ምልክቱን ይጫኑ። የመጨረሻው ዓምድ ግምታዊ የአነባበብ መመሪያ ይሰጣል።",
  "Say it like": "እንዲህ ይበሉት",
  "round lips for ü": "ለü ከንፈርዎን ያክብቡ",
  "\"tsv-\" + round lips for ö": "«ትስቭ-» + ለö የተከበበ ከንፈር",
