  "At the embassy, at the doctor's or on the phone you will often hear: <em class=\"de\">Wie schreibt man das?</em> (How do you spell that?) Then you spell your name with the German letter names.": "በኤምባሲ፣ በሐኪም ዘንድ ወይም በስልክ ብዙ ጊዜ ይህን ይሰማሉ፦ <em class=\"de\">Wie schreibt man das?</em> (ይህ እንዴት ይጻፋል?) ከዚያም ስምዎን በጀርመንኛ የፊደል ስሞች ፊደል በፊደል ይናገራሉ።",
  "Many letters sound close to English. Watch out for the vowels and for <strong>J, V, W, Y, Z</strong>.": "ብዙ ፊደላት ከላቲን ፊደል ስሞች ጋር ይቀራረባሉ። አናባቢዎቹንና <strong>J, V, W, Y, Z</strong>ን ልብ ይበሉ።",
  "The letters": "ፊደላቱ",
  "A to Z, plus ä, ö, ü and ß": "ከA እስከ Z፣ እንዲሁም ä፣ ö፣ ü እና ß",
  "Press a speaker to hear each group of letters.": "እያንዳንዱን የፊደል ቡድን ለመስማት የድምፅ ምልክቱን ይጫኑ።",
  "Say them": "እንዲህ ይባላሉ",
