  "E = e": "E = e",
  "sounds like \"ay\"": "«ኤ» ይባላል",
  "Spell and listen": "ፊደል በፊደል ያዳምጡ",
  "Listen to the spelling, then choose the name.": "ፊደል በፊደል ሲነገር ያዳምጡ፤ ከዚያም ስሙን ይምረጡ።",
  "Listen to the spelling, then choose the town.": "ፊደል በፊደል ሲነገር ያዳምጡ፤ ከዚያም ከተማውን ይምረጡ።",
