  "Put the conversation in order.": "ውይይቱን በቅደም ተከተል ያስቀምጡ።",
  "Two classmates": "ሁለት የክፍል ጓደኞች",
  "Read the text. Press a speaker to hear each part, and use the word list below it.": "ጽሑፉን ያንብቡ። እያንዳንዱን ክፍል ለመስማት የድምፅ ምልክቱን ይጫኑ፤ ከሥሩ ያለውን የቃላት ዝርዝርም ይጠቀሙ።",
  "Then answer the questions. The text stays on screen while you do.": "ከዚያም ጥያቄዎቹን ይመልሱ። በሚመልሱበት ጊዜ ጽሑፉ ስክሪኑ ላይ ይቆያል።",
