  "<em class=\"de\">sein</em> means <strong>to be</strong>. It is irregular: every form has to be learned by heart, but you will use it all the time.": "<em class=\"de\">sein</em> ማለት <strong>መሆን</strong> ነው። ደንብ የማይከተል ግሥ ነው፤ እያንዳንዱን ቅርጽ በቃል መያዝ ያስፈልጋል፤ ግን ሁልጊዜ ይጠቀሙበታል።",
