  "<em class=\"de\">sprechen</em> (to speak) is a <strong>stem-changing verb</strong>: in the du and er/sie/es forms the <strong>e</strong> of the stem becomes <strong>i</strong>. The endings stay regular.": "<em class=\"de\">sprechen</em> (መናገር) <strong>ሥሩ የሚቀየር ግሥ</strong> ነው፦ በdu እና በer/sie/es ቅርጾች ውስጥ የሥሩ <strong>e</strong> ወደ <strong>i</strong> ይቀየራል። መጨረሻዎቹ ግን መደበኛ ናቸው።",
